alimento, formar el bolo y empujarlo para deglutir.","OPCION_D":"Dividir el glóbulo en gotas pequeñas para aumentar la superficie disponible.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Dividir el glóbulo en gotas pequeñas para aumentar la superficie disponible.","FUENTE":"Saladin, Anatomía y fisiología: la unidad entre forma y función","PAGINAS_PDF":"981–1022"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;

