ión y análisis antes del trabajo de campo?","OPCION_A":"Para aportar conocimiento o ayudar a resolver el problema que motivó la investigación.","OPCION_B":"Para organizar cómo se obtendrán y analizarán datos capaces de responder la pregunta de investigación.","OPCION_C":"Para decidir cómo ordenar, presentar e interpretar los datos que se obtengan.","OPCION_D":"Porque los datos son la materia prima de los análisis y hallazgos posteriores.","RESPUESTA_CORRECTA":"C","EXPLICACION":"Para decidir cómo ordenar, presentar e interpretar los datos que se obtengan.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–47"},{"MATERIA":"SALUD PUBLICA","TEMA":"proceso de investigacion","DIFICULTAD":"facil","PREGUNTA":"¿Qué actividades integran la ejecución del estudio?","OPCION_A":"Cómo vive, actúa y entiende la situación la gente involucrada.","OPCION_B":"De la práctica, debates, publicaciones, noticias o vacíos del conocimiento, entre otras fuentes.","OPCION_C":"Revisar antecedentes y analizar qué aspecto relevante falta estudiar.","OPCION_D":"Recolectar, procesar, analizar e interpretar los datos, y elaborar conclusiones y recomendaciones.","RESPUESTA_CORRECTA":"D","EXPLICACION":"Recolectar, procesar, analizar e interpretar los datos, y elaborar conclusiones y recomendaciones.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–47"},{"MATERIA":"SALUD PUBLICA","TEMA":"proceso de investigacion","DIFICULTAD":"dificil","PREGUNTA":"¿Por qué una mala recolección de datos afecta todo el estudio?","OPCION_A":"Porque los datos son la materia prima de los análisis y hallazgos posteriores.","OPCION_B":"Porque sus momentos se relacionan y pueden revisarse conforme avanza el estudio.","OPCION_C":"Para organizar cómo se obtendrán y analizarán datos capaces de responder la pregunta de investigación.","OPCION_D":"Para decidir cómo ordenar, presentar e interpretar los datos que se obtengan.","RESPUESTA_CORRECTA":"A","EXPLICACION":"Porque los datos son la materia prima de los análisis y hallazgos posteriores.","FUENTE":"Educación en Salud e Investigación CB24-25","PAGINAS_PDF":"40–47"}]'::jsonb) AS p("MATERIA" text, "TEMA" text, "DIFICULTAD" text, "PREGUNTA" text, "OPCION_A" text, "OPCION_B" text, "OPCION_C" text, "OPCION_D" text, "RESPUESTA_CORRECTA" text, "EXPLICACION" text, "FUENTE" text, "PAGINAS_PDF" text)
), missing AS (
  SELECT p.* FROM payload p
  WHERE NOT EXISTS (
    SELECT 1 FROM public.banco_preguntas b
    WHERE b."MATERIA" = p."MATERIA" AND lower(b."PREGUNTA") = lower(p."PREGUNTA")
  )
), numbered AS (
  SELECT (SELECT coalesce(max(id), 0) FROM public.banco_preguntas) + row_number() OVER (ORDER BY "MATERIA", "TEMA", "PREGUNTA") AS id, m.*
  FROM missing m
)
INSERT INTO public.banco_preguntas (id, "MATERIA", "TEMA", "DIFICULTAD", "PREGUNTA", "OPCION_A", "OPCION_B", "OPCION_C", "OPCION_D", "RESPUESTA_CORRECTA", "EXPLICACION", "FUENTE", "PAGINAS_PDF")
SELECT n.id, n."MATERIA", n."TEMA", n."DIFICULTAD", n."PREGUNTA", n."OPCION_A", n."OPCION_B", n."OPCION_C", n."OPCION_D", n."RESPUESTA_CORRECTA", n."EXPLICACION", n."FUENTE", n."PAGINAS_PDF" FROM numbered n;
COMMIT;
